uniform shader image;
uniform float2 size;
uniform float time;
uniform float contrast;
uniform float pivot;
uniform float gamma;

half4 main(float2 coord){half4 c=image.eval(coord);half3 s=c.rgb/max(c.a,0.0001);s=(s-half3(pivot))*half(contrast)+half3(pivot);s=pow(max(s,half3(0)),half3(1.0/max(gamma,0.01)));return half4(clamp(s,half3(0),half3(1))*c.a,c.a);}
